{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background While it is now apparent clinical sequelae (long COVID) may persist after acute COVID-19, their nature, frequency and aetiology are poorly characterised.",
      "reason": "Explicitly describes the current state of knowledge and highlights important uncertainties about the nature, frequency and aetiology of long COVID."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We conducted a 'living' systematic review to provide frequently updated evidence on the symptoms and complications of long COVID.",
      "reason": "States the purpose and importance of conducting this living systematic review to provide up-to-date evidence on long COVID symptoms and complications."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Systematic reviews conducted early during the COVID-­ 19 pandemic soon became redundant due to the rapidity with which new research was released.",
      "reason": "Explains why earlier systematic reviews were insufficient and justifies the need for a living review updating evidence as new research emerges."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review concerns characterization of long COVID (symptoms and complications), not evaluation of an intervention; no mechanism of action is relevant or discussed."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not concern a complex intervention or delivery context, so a logic model is not applicable."
    }
  ],
  "confidence": 85
}

{
