  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "This study aims to regularly synthesise evidence on long COVID characteristics, to help inform clinical management, rehabilitation strategies and interventional studies to improve long-­ term outcomes.",
      "reason": "The manuscript provides an explicit statement of the review objective (to synthesise evidence on long COVID characteristics and inform clinical management etc.), but it does not present the objective using a formal question-formulation framework (e.g., PICO, PECOS) as required by the item."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "We conducted a 'living' systematic review to provide frequently updated evidence on the symptoms and complications of long COVID.",
      "reason": "The review addresses characteristics, symptoms and complications of long COVID rather than effects of interventions; therefore specifying planned comparisons using PICO for intervention effects is not applicable."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Peer-­ reviewed studies were considered eligible if they included at least 100 people with laboratory confirmed and/or clinically diagnosed COVID-­ 19. Without a clear, internationally agreed case definition, we included studies that reported symptoms or outcomes assessed at 12 or more weeks post COVID-­ 19 onset. 6",
      "reason": "The eligibility criteria specify key study characteristics: minimum sample size (>=100), case definition (laboratory confirmed and/or clinically diagnosed COVID-19) and minimum follow-up (>=12 weeks)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The following databases were searched: Medline and CINAHL (EBSCO), Global Health (Ovid), WHO Global Research Database on COVID-­ 19 and LitCovid from 1 January 2020 to 17 March 2021.",
      "reason": "The search time window (dissemination years covered) is specified. Additional supporting evidence: text_12 states 'There were no language restrictions.' and text_14 states data extraction was not performed for non-peer-reviewed preprints, indicating publication/report status criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved text explicitly distinguishes excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "We presented symptom proportions by different settings, as presented in the individual studies: hospitalised, non-­ hospitalised or a mix of both populations if no subset data were available. Symptoms were broadly grouped into physiological clusters through discussion with clinicians.",
      "reason": "The synthesis groups (hospitalised, non-hospitalised, mixed) are specified and linked to subgroup/meta-analyses addressing setting and other comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Studies were excluded if they included fewer than 100 participants, to avoid small study effects, 18 or the follow-­ up was unclear or less than 12 weeks post onset.",
      "reason": "A clear rationale is provided for the sample-size restriction (to avoid small study effects) and for follow-up requirement, satisfying the requirement to justify notable restrictions; additional rationale for excluding non-peer-reviewed preprints is given in text_14."
    }
  ],
  "confidence": 85
}

